window.__vaultPreview("d3e67147fa363c04",{"text":"{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"@id\":\"https://pipelinersusa.com/cracked-vs-collapsed-sewer-pipes-whats-the-difference/#faq\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Can a cracked sewer pipe be lined?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Usually, yes. A cracked pipe still holds its shape, so a cured-in-place liner can be pulled in and cured against the old wall, sealing the cracks from the inside. Pipeliners cures its liners with UV LED light, and the finished liner carries a 50-year life expectancy.\"}},{\"@type\":\"Question\",\"name\":\"Can a collapsed sewer line be lined?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Not the collapsed section itself, because a liner needs an open pipe to form against. The usual fix is to dig up and replace the collapsed spot, then line the rest of the line from the inside.\"}},{\"@type\":\"Question\",\"name\":\"How do I know if my sewer line is cracked or collapsed?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A sewer camera inspection is the only reliable way. From the surface the symptoms overlap, but the camera shows whether the pipe is cracked and still round or has caved in.\"}},{\"@type\":\"Question\",\"name\":\"Is a cracked sewer pipe an emergency?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Not usually, but it gets worse. Cracks let roots in and can wash out the soil around the pipe, which is how a crack turns into a collapse. Frequent backups or sewage in the yard need attention right away.\"}}]}"});
